  ('darksiders-2', 'https://res.cloudinary.com/dsvkbe0mc/image/upload/v1785114608/maps/s3gzkujoslz5xqdj2osj.webp', 'Shadows Edge', 4)
) AS x(slug, image_url, alt_text, sort_order)
WHERE g.slug = x.slug
ON CONFLICT DO NOTHING;

