-- ============================================================
-- Adventures (resuelve guía por (game_slug, guide_sort); sort_order 1-based)
-- guide_sort es el sort_order reindexado de la guía (único por juego)
-- ============================================================
INSERT INTO gg_adventures (guide_id, description, is_important, is_optional, sort_order)
SELECT gr.id, x.description, x.is_important, x.is_optional, x.sort_order
FROM gg_games g, gg_guides gr, (VALUES
  ('chrono-cross', 'Final oculto: Darkened Fate (Final 7/11)', 35, E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer después de que Harle abandona tu grupo', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Hermits Hideaway', 34, E'✓ Habla con Riddel (Personaje 35/45) y se te unirá\n✓ Se te unirán Viper (Personaje 36/45), Fargo (Personaje 37/45) y Mercy (Personaje 38/45)... (Zoah o Karsh)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', 33, E'✓ Ve a Guldove y Lucha con Orlha y conseguirás su Sapphire Brooch (Ítem /56), devuélvesela cuando seas Serge de nuevo, y se te unirá\n✓ Dale al Doc. el libro para desbloquear su habilidad', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', 33, E'✓ Ve Water Dragon Isle y a Un tipo te dará el Sturdy Ribs (Item /56) de Skelly', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', 33, E'✓ Ve a Isle of the Damned, recoge los Mixed Bones (Ítem /56) de Skelly en la cueva al noroeste de la primera pantalla', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', 33, E'✓ Si ya tienes todas las 6 partes de Skelly (Heavy Skull, Pelvic Bone, Mixed Bones, Angry Scapula, Good Backbone, Sturdy Ribs) ve a Termina a la casa de la derecha de la estatua de Viper, y se te unirá Skelly (Personaje 34/45) si hablas con la abuela', FALSE, FALSE, 4),
  ('chrono-cross', 'Final oculto: Onward Dragoons (Final 6/11)', 32, E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer inmediatamente después de rescatar a Riddel', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Ve a Viper Manor, habla con Norris en la habitación del oeste de la entrada y te dará la Prison Key (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Gira la estatua de la serpiente, y cae en la trampa', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Si vas a la cárcel, encontraras una la Parlor Key (Item /56)', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Lucha con los guardias, coge su ropa y entra en las habitaciones de la parte izquierda\n✓ En la cocina, habla con Glenn, ve a su habitación, y te escribirá la combinación de la estatua', FALSE, FALSE, 4),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Ve a las alcantarillas desde la cocina, encuentra y apaga la válvula\n✓ Vuelve a la primera sección, ahora ya puedes cruzar, y apaga la segunda válvula\n✓ En la siguiente pantalla, sube la válvula y vuelve al otro lado\n✓ Bájala, procede, y lucharas contra un bicho gordo, procede subir las escaleras', FALSE, FALSE, 5),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ En las habitaciones de la derecha, recoge todos los artículos y el pendiente para caer en otra trampa\n✓ Lucha con los bichos de Luccia\n✓ Libera al criatura que esta enjaulada', FALSE, FALSE, 6),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Lucharas contra Dark Orcha para rescatar a Riddel, luego se te unirá Orcha (Personaje 32/45)\n✓ Sigue recto hacia la biblioteca, lucharas con Grovyc y Mecha\n✓ Escapa hacia la biblioteca, lucha con Mecha otra vez, y escapa por la ventana\n✓ Grobyc (Personaje 33/45) se unirá a tu grupo', FALSE, FALSE, 7),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ La habitación que esta al lado del laboratorio podrás conseguir el Decor Shield (Item /56), si la colocas en la armadura sin escudo encontraras una habitación secreta', FALSE, FALSE, 8),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Vuelve a la entrada y usa la combinación apropiada en la estatua de la serpiente\n✓ Ve al oeste, a la biblioteca, veras a Balthasar (Chrono Trigger), lucha con Marcy\n✓ Obtén el marco Porres Furnace (Marco 7/15)', FALSE, FALSE, 9),
  ('chrono-cross', '(AW) Viper Manor', 31, E'✓ Habla con el viejo, vuelve a la habitación grande, busca en las columnas un botón que accione el ascensor\n✓ Lucha con los guardias, toma el ascensor y pasa la puerta\n✓ Lucha contra Lynx, habrá unas cuantas escenas', FALSE, FALSE, 10),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', 30, E'✓ Viaja por el portal de la playa a (AW)\n✓ ve a Hydra Marshes y explora todo lucha con jefes obtendrás una habilidad especial, mas adelante en una lagunilla obtén el Life Sparkle (Ítem /56) y Busca el Good Backbone (Ítem /56) de Skelly en una cueva (por la zona este)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', 30, E'✓ Ve al bar de Termina, hay una habitación secreta, aquí podrás reclutar a Zoah (Personaje 30/45) o Karsh (Personaje 31/45), si quieres obtener a los 2 deveras terminar el juego e iniciar (NG+) Pero si eliges a Karsh, Zoha se te unirá en el S.S Zelbess también obtendrás el Tear of Hate (Ítem /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', 30, E'Opción 1: Consigue a Zoah', TRUE, FALSE, 3),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', 30, E'Opción 2: Consigue a Karsh', TRUE, FALSE, 4),
  ('chrono-cross', '(HW) Mar del Edén', 29, E'✓ Ve al The Dead Sea, recoge todos los cofres\n✓ Habla con el fantasma y se le caerá algo, recógelo y Obtén el Station Pass (Item /56) con este ítem podrá obtener el Medical Book (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Mar del Edén', 29, E'✓ ve al The Dead Sea y usa la Fiddler Crab, entra y veras la Masamune\n✓ Despues de hablar, ve a la Hermits Hideaway (HW), habla con Radius y recibe el Garais Keepsake (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Mar del Edén', 29, E'✓ Obtén el Prop Sword (Item /56)', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Mar del Edén', 29, E'✓ Lucha con Miguel, y la ciudad será destruida (el Dragon del Cielo te salvara)', FALSE, FALSE, 4),
  ('chrono-cross', '(HW) Isla Maldita', 28, E'✓ Llega al espejo de la izquierda del todo (bajando por el esqueleto serpiente)\n✓ Lucha con Garai (a llorar a la playa)\n✓ Obtén la Einlanzer (Item /56) y úsala para destruir la Masamune en Dead Sea', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Mar del Edén', 27, E'✓ Ve al The Dead Sea, recoge todos los cofres\n✓ Habla con el fantasma y se le caerá algo, recógelo y Obtén el Station Pass (Item /56) con este ítem podrá obtener el Medical Book (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Mar del Edén', 27, E'✓ ve al The Dead Sea y usa la Fiddler Crab, entra y veras la Masamune\n✓ Despues de hablar, ve a la Hermits Hideaway (HW), habla con Radius y recibe el Garais Keepsake (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Mar del Edén', 27, E'✓ Obtén el Prop Sword (Item /56)', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Mar del Edén', 27, E'✓ Lucha con Miguel, y la ciudad será destruida (el Dragon del Cielo te salvara)', FALSE, FALSE, 4),
  ('chrono-cross', '(HW) El Zelbess de Fargo', 26, E'✓ Intenta cruzar la puerta del fondo del barco, Fargo te debe dar permiso, abre la puerta siguiente y veras a un orejón que hace aseo, háblale\n✓ Ve a pedirle a Fargo permiso para cruzar la puerta, te hará juega a la Roulette y perderás. ve a la primera puerta debajo del casino, veras algo sospechoso', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) El Zelbess de Fargo', 26, E'✓ Mira el show de Sneff, convertirá a alguien en gato, sale y vuelve a entrar para que Sneff te convierta en gato\n✓ Mientras seas gato y le hablas al gato de la cocina podrás obtener el Monsters Mouth (Marco 13/15)\n✓ Entra en el en la habitación que esta debajo de la ruleta, roba el Handle (Item /56)\n✓ Ve donde Sneff y que te vuelva a convertir, juega a la Roulette con Fargo otra vez. Perderá, ahora cruza esa puerta', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) El Zelbess de Fargo', 26, E'✓ Si ganas los 3 combates del SLAM podrás reclutar a Janice (Personaje 26/45)\n✓ Lucha contra el Sabio y obtén la Fiddler Crab (Item /56)\n✓ Ve al casino donde esta la ruleta, luego ve a la segunda habitación bajando las escaleras y reclutaras a Sneff (Personaje 27/45)\n✓ Sube a la cubierta y luego por el mástil, aquí se unirá Irenes (Personaje 28/45)', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Nido Triangle | Sky Dragon Isle | Marbule', 25, E'✓ Ve al Nido Triangle, nada hasta el fondo y obtén el Star Fragment (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Nido Triangle | Sky Dragon Isle | Marbule', 25, E'✓ Ve a Sky Dragon Isle e intenta abrir el cofre, lucha contra Starky (Personaje 25/45) y véncelo para reclutarlo, obtén Our Favorite Martian (Marco 11/15)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Viper Manor', 24, E'✓ Con Radius ve a Termina a buscar a Norris, luego entra por el Shadow Forest, después de hablar con el niño salvar a un hombre, golpeando a un insecto ahogado, y te dará el Mushroom (Item /56). Puedes obtener Funguy (Personaje 40/45) si le das el champiñón al hombre de la cueva', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Viper Manor', 24, E'✓ Ve por las mazmorras, si no puedes pasar tendrás que ir por la entrada principal y bajar por el pozo. Habla con Norris (Personaje 24/45), se te unirá si Radius esta contigo', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Viper Manor', 24, E'✓ Ve a Termina, ahora podrás usar un bote inflable donde estaba el barco de Nikki', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Termina', 23, E'✓ Intenta cruzar el portal para ir a (HW) en la playa luego intenta cruzar el Fossil Valley\n✓ Ve a Arni Village, habla con Marge y lucha contra Radius (Personaje 21/45) para reclutarlo', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Termina', 23, E'✓ Cruza el Fossil Valley y consigue el Infrared Vision (Marco 10/15)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Termina', 23, E'✓ Ve Termina para reclutara Zappa (Personaje 22/45) este te data el Smith Spirit (Item /56) y a Van (Personaje 23/45)', FALSE, FALSE, 3),
  ('chrono-cross', 'Final oculto: New Beginnings (Final 5/11)', 22, E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer con Lynx', FALSE, FALSE, 1),
  ('chrono-cross', 'Mundo Abstracto y el Más Allá', 21, E'✓ Hola Lynx (Personaje 18/45), toma una manzana del árbol y Sprigg vendrá\n✓ Entra en su casa y podrás reclutar a Sprigg (Personaje 19/45)\n✓ Ve al norte, sigue a Serge a cada puerta que vaya (en tu piso)\n✓ Harle (Personaje 20/45) se te une, avanza, escapa por el agujero y aparecerás en Hydra Marsh', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Fort Dragonia', 20, E'✓ Resuelve todos los puzzles y jefes\n✓ Debes vencer al SOL (Hincha Pelotas), toma el ascensor\n✓ Lynx y Viper estarán aquí, continua la historia...', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: The Magical Dreamers (Final 4/11)', 19, E'Antes de terminar la Fortaleza, crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer con la siguiente formación Nikki, Razzly y Kid, Para reemplazar a Serge del equipo puede usar el Relief Charm (Item /56) que obtienes al iniciar la partida NG+', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Costa Este de El Nido', 18, E'✓ Cruza el Monte Piro, usa el Ice Breath para congelar la lava\n✓ Te recomiendo recoger todos los cofres primero antes de congelar todo\n✓ Cruza todo el Monte hasta llegar a Fort Dragonia', FALSE, FALSE, 1),
