  ('chrono-cross', '(AW) Another World', 5, E'✓ Leena (Personaje 3/45) y Poshul (Personaje 4/45) se te unirán ahora, (es la única manera de conseguir a Leena)', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Another World', 5, E'✓ Ve donde conseguiste el Shark Tooth Amulet y muéstraselo al predicador, se te unirá Mojo (Personaje 2/45) al salir de allí', FALSE, FALSE, 4),
