  ('chrono-cross', 'Final oculto: Programmers Ending (Final 1/11)', 2, E'Cuando despiertes crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer inmediatamente sin reclutar compañeros', TRUE, FALSE, 1),
  ('chrono-cross', 'El Sueño', 1, E'Partidas guardadas', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Preparación', 37, E'✓ Primero ve al S.S Zelbess (HW) lleva a Fargo a verse asimismo', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Preparación', 37, E'✓ Después del concierto ve a Marbule y vence a todos los monstruos, cuando vuelvas podrás reclutar a Miki (Personaje 29/45)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Preparación', 37, E'✓ Ve a Hydra Marshes (HW) y consigue la Ancient Fruit (Ítem /56), si no te la da el bicho ve a (AW) al mismo lugar para que te la de, luego vuelve', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Dragón Verde', 38, E'✓ En Hydra Marshes, usa la Beeba Flute cerca del segundo Beeba\n✓ El bicho Hydra te llevara a Gaeas Navel, aquí reclutas a Leah (Personaje 42/45)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Dragón Verde', 38, E'✓ Roba la armadura cuando este debilitado, al vencerlo te dará la Green Relic (Ítem /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Dragón de Agua', 39, E'✓ Ve a la Isla del Dragon de Agua (Water Dragon Isle), esta al final del todo\n✓ Roba la armadura cuando este debilitado, al vencerlo te dará la Blue Relic (Ítem /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Dragón de Tierra', 40, E'✓ Ve a Cleared Earth Dragon Isle, entra por las arenas movedizas\n✓ Debes ir a la izquierda y abajo de la cueva, obtén los Explosive (Ítem /56) del NPC, si el NPC no esta trata de mover a la tortuga, luego sale de la isla y vuelve a entrar', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Dragón de Tierra', 40, E'✓ Debes matar y poner cada tortuga en los agujeros geiser con los explosivos\n✓ Salta dentro del nuevo agujero y lucha con el dragon\n✓ Roba la armadura cuando este debilitado, al vencerlo te dará la Yellow Relic (Ítem /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Dragón de Fuego', 41, E'✓ Ve al monte del Dragon de Fuego en Mount Pyre (AW)\n✓ Ve a la cascada de lava, baja a la primera cascada y entra por la puerta\n✓ Roba la armadura cuando este debilitado, al vencerlo te dará la Red Relic (Ítem /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Dragón Negro', 42, E'✓ Ve a Marbule (AW), el dragón estará en la cueva, habla con el NPC y te dará el Quill and Papyrus (Marco 15/15)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Dragón Negro', 42, E'✓ Si tienes a Pierre, no tendrás que luchar con el para la Black Crest\n✓ Roba la armadura cuando este debilitado, al vencerlo te dará la Black Relic (Ítem /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Dragón del Cielo', 43, E'✓ Ve a Sky Dragon Isle y lucha con el dragón\n✓ Roba la armadura cuando este debilitado, al vencerlo te dará la White Relic (Ítem /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Criosphinx', 44, E'Esta Misión es opcional (No es Importante) debes ir a Earth Dragon Isle y... (a llorar a la playa por la paliza que te dara) sino esperar a la partida (NG+)', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Criosphinx', 44, E'✓ Este dragón es el jefe mas difícil del juego, aun mas que el jefe final\n✓ El truco para vencerlo es responder correctamente sus acertijo o luchando a fuerza bruta\n✓ Si lograste robar la armadura con Fargo al dragón de tierra (Coraza Dorada) lo vencerás en cuestión de tiempo\n✓ De lo contrario será un jefe difícil, debes llevar muchas curas y trampas de elemento como Terremoto y Tormenta Eléctrica\n✓ Si lo vences te dará las Gafas de Sol, uno de los mejores artículos de equipamiento del juego', FALSE, TRUE, 2),
  ('chrono-cross', '(AW) Guldove', 45, E'✓ Muestra el cristal roto a Direa y Steena, y consigue el Dragon Emblem (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove', 45, E'✓ Ensenaselo al guardia de la tienda de Steena en Guldove (HW) y ella te dara el Dragon Tear (Item /56)\n✓ Ahora Steena (Personaje 43/45) se te unirá, Lleva a Steena a Fort Dragonia', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Fuerte Dragonian', 46, E'✓ Ve a Fort Dragonia\n✓ Pon el amuleto en la ranura de la entrada\n✓ Lucha contra Dark Serge en la sala del ascensor\n✓ Baja, pon el huevo gigante en el centro y y obtendrás a Draggy (Personaje 44/45)\n✓ Sube a la habitación principal y abre la puerta, aquí obtendrás el Tear of Love (Ítem /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) La Búsqueda de la Masamune', 47, E'✓ Esta misión es opcional y difícil, Necesitaras a Riddel y Karsh\n✓ Lucha con Solt y Peppor en Isle of the Damned (AW) y obtendrás el Memento Pendant (Ítem /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) La Búsqueda de la Masamune', 47, E'✓ Ve a la isla escondida al noreste de El Nido (HW)\n✓ Usa el pendiente y esto hara que luches con Dario (a llorar a la playa)\n✓ La Masamune se transformara en la la Mastermune, la mejor arma de Serge\n✓ Pon a Glenn en posición principal y llévalo a la tumba de Dario\n✓ Ve a Termina y procura de que Glen NO tenga equipada la Einlanzer, ve a la tumba familiar de Glen y obtén la Einlanzer doble', FALSE, FALSE, 2),
  ('chrono-cross', 'Final oculto: Career Change (Final 8/11)', 48, E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer después de vencer a Dario y antes de que aparezca Terra Tower', TRUE, FALSE, 1),
  ('chrono-cross', '(HW) Mar de Edén', 49, E'✓ Si quieres reclutar a Orlha (Personaje 45/45), ve a Guldove (AW) y dale el Sapphire Brooch\n✓ Si tienes a Glenn, ahora le puedes equipar la Einlanzer\n✓ Lleva a Steena al Sea of Eden y entra en uno de los agujeros\n✓ Ve a cada una de las islas\n✓ En la tercera tendrías que luchar contra los Destinos', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Chronopolis', 50, E'✓ Se vienen los Mecha\n✓ Encuentra la entrada a la sala de ordenadores y ve a la base\n✓ Usa el control remoto robot para accionar el puente\n✓ En la habitación principal, ve a la derecha hacia la habitación de las escaleras\n✓ Hay un objeto importante para Grobyc en el cofre del fondo de todo', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Chronopolis', 50, E'✓ En el segundo piso hay una habitación donde puedes activar el elevador\n✓ En el tercero y cuarto piso, obsérvalo todo, pero no puedes entrar en una habitación\n✓ En el primer piso, en el muelle, habla con el fantasma azul\n✓ Ve a la habitación donde no pudiste entrar y coge la Card Key (Ítem /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Chronopolis', 50, E'✓ Ahora que el Séptimo dragón esta aquí, el séptimo elemento es activado', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Cascadas Divinas de los Dragones', 51, E'✓ Ve al Divine Dragon Falls que están justo al este del Fossil Valley\n✓ Usa los 2 fragmentos de cristal en los pilares, el Tear of Hate y el Tear of Love\n✓ Ahora conseguirás el Chrono Cross (Ítem /56), y el elemento. Ponla en la primera ranura de Serge', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Cascadas Divinas de los Dragones', 51, E'✓ Presta atención en las bolas de colores que aparecen ahora en batalla, son importantes', FALSE, FALSE, 2),
  ('chrono-cross', 'Cosas por Hacer', 52, E'✓ Ve a la casa de casa de Radius en Hermits Hideaway (HW) con Poshul en tu equipo\n✓ Podrás reclutar a Turnip (Personaje 39/45) para esto debes haber usa el Ice Breath o la Ice Gun en el suelo en Hermits Hideaway (AW)', FALSE, FALSE, 1),
  ('chrono-cross', 'Cosas por Hacer', 52, E'✓ Ve a la pileta de Viper Manor (AW) con el Life Sparkle y obtendrás a Neofio (Personaje 41/45)', FALSE, FALSE, 2),
  ('chrono-cross', 'Cosas por Hacer', 52, E'✓ Ve con Viper en tu equipo podrás conseguir los cofres de la sala secreta, después de leer la carta en la oficina secreta\n✓ Para entrar a la oficina secreta, debes mover la cabeza de la estatua de la izquierda', FALSE, FALSE, 3),
  ('chrono-cross', 'Cosas por Hacer', 52, E'✓ Ve a Gaeas Navel (AW) vence al cavernícola del árbol y consigues el Snakes & Orbs (Marco 14/15)', FALSE, FALSE, 4),
  ('chrono-cross', '(AW) Hermits Hideaway', 53, E'✓ Ve a Hermits Hideaway, veras a Kid\n✓ Si tienes la Mastermune, entraras en un sueno\n✓ En casa de Lucca, busca por ahí y hay una puerta trampilla en la habitación de arriba derecha\n✓ En la primera habitación, pulsa L2, Triangulo, R2, y Triangulo en la maquina\n✓ Obtendrás el Ataque de nivel 7 de Kid\n✓ Necesitaras la Ice gun (Ítem /56) de Lucca para apagar las llamas\n✓ Rescata a todos los niños hasta que alcances a Kid y el sueno se acabara', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) El Nido Triangle', 54, E'✓ Ve con Starky, y lucha con el pez gigante en el fondo del mar\n✓ El Pez gigante es solo débil al fuego, no a los ataques físicos\n✓ Ahora vuela con el bote hacia Dinopolis', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: Return of the Downtrodden (Final 9/11)', 55, E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer antes de terminar Terra Tower', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Dinopolis y Terra Tower', 56, E'✓ Venciendo a los seis guardianes elementales\n✓ Se recomienda usar elementos trap para robar las invocaciones\n✓ Al final, te encontraras al Dragon Lunar\n✓ Atiende al orden de colores a los que cambia, y anótalos XD, igual los anote por ti\n✓ Si lo vences, la Llama Congelada se perderá en una corriente temporal\n✓ Obtendrás el Time Egg (Ítem /56), este ítem lo obtendrás en la partida NG+', TRUE, FALSE, 1),
  ('chrono-cross', '(HW) Playa Opassa', 57, E'✓ Ve a la playa que gatillo todos los eventos de tu historia\n✓ Habla con los Chrono, Lucca y Marle\n✓ Acá podrás sacar 2 finales Distintos uno bueno y el otro malo, crea un guardado independiente de la partida principal, cuando termines el juego NO guardes la partida nueva, sino que carga esta partida de forma normal para sacar el otro final.\n✓ Usa el Time Egg encima del agujero de gusano lila para la batalla final y al terminar el juego recuperaras el Time Egg en el (NG+)', FALSE, FALSE, 1),
  ('chrono-cross', 'Final: True Ending (Final 10/11)', 58, E'✓ Salva a Schala del Time Devourer tocando el Chrono Cross\n✓ Para esto debes crear la secuencia de colores que realizo el Dragon Lunar', FALSE, FALSE, 1),
  ('chrono-cross', 'Final: True Ending (Final 10/11)', 58, E'Lanza elementos en este orden: Amarillo, Rojo, Verde, Azul, Negro, Blanco, y Chrono Cross', TRUE, FALSE, 2),
  ('chrono-cross', 'Final: True Ending (Final 10/11)', 58, E'✓ Ayuda si esperas a que todos puedan usar hasta la octava fila\n✓ Usa magias de curación de modo que el Time Devourer no lo cuente ni interrumpa tu orden de bolas', FALSE, FALSE, 3),
  ('chrono-cross', 'Final: Bad Ending (Final 11/11)', 59, E'Mata al Time Devourer junto a Schala! Sin usar la secuencia de colores', TRUE, FALSE, 1),
  ('chrono-cross', 'Consideraciones', 60, E'Bend of Time, es un área oculta que solo se puede acceder en una partida NG+, aquí puedes luchar contra Ozzie, Slash y Flea, personajes de Chrono Trigger, los puedes capturar para el Dopellgang de Sprigg', TRUE, FALSE, 1),
  ('chrono-cross', 'Consideraciones', 60, E'Los 10 portales del Bend of Time son los siguientes. 1: Lizard Rock. 2: Viper Manor, Viper Manor Bluffs. 3: Water Dragon Isle, Hydra Marshes, S. S. Invincible. 4: Fort Dragonia, Temporal Vortex. 5: Shadow Forest, Fossil Valley, 6: Mt. Pyre, Isle of the Damned. 7: Dead Sea, 8: Marbule, Gaeas Navel, Earth Dragon Isle. 9: Chronopolis, Sea of Eden. 10: Terra Tower, Luccas House.', TRUE, FALSE, 2),
  ('chrono-cross', 'Consideraciones', 60, E'Para obtener a los 46 personajes se debe recorrer el juego al amenos 3 veces seguida usando el NG+ y usar el Chrono Cross en la casa de Sprigg', TRUE, FALSE, 3),
  ('chrono-cross', 'Consideraciones', 60, E'Con el Chrono Cross puedes recuperar todos los personajes de las partidas anteriores PERO, para poder considerar a Harle, debes terminar el juego con Lynx y Harle e iniciar el NG+', TRUE, FALSE, 4),
  ('chrono-cross', 'Consideraciones', 60, E'Para obtener Guile, Nikki y Pierre se debe hacer en 3 pasadas, no se puede conseguir en una partida', TRUE, FALSE, 5),
  ('chrono-cross', 'Consideraciones', 60, E'Para obtener Korcha, Mel ,Razzly o Macha, Glen, Doc. se debe hacer en 2 pasadas, no se puede conseguir en una partida', TRUE, FALSE, 6),
  ('chrono-cross', 'Consideraciones', 60, E'Leena solo se puede obtener rechazando a Kid 3 veces en Cape Howl', TRUE, FALSE, 7),
